 print(name, 'bytes=',p.stat().st_size, 'type=',type(d).__name__)
 if isinstance(d,dict):
  for k,v in d.items(): print(k, type(v).__name__, len(v) if hasattr(v,'__len__') else '')
 elif isinstance(d,list):
  for i,v in enumerate(d): print('ITEM',i, {k: (len(x) if isinstance(x,(str,list,dict)) else x) for k,x in v.items()})
